const path = require("node:path");
const {
  PBXFileReference,
  PBXNativeTarget,
  XCRemoteSwiftPackageReference,
  XCSwiftPackageProductDependency,
} = require("@bacons/xcode");
const {
  withXcodeProjectBeta,
} = require("@bacons/apple-targets/build/with-bacons-xcode");

const WIDGET_TARGET_NAME = "OrbitWidget";
const MATH_PACKAGE_URL = "https://github.com/PhraseHQ/SwaTex";
const MATH_PACKAGE_VERSION = "0.5.0";
const MATH_PRODUCT_NAME = "SwaTexRender";

// The Xcode project is generated by Expo, so declare the widget-only Swift
// dependency here rather than relying on changes made directly in ios/.
function ensureMathRenderingPackage(project, widgetTarget) {
  const packageReferences = (project.rootObject.props.packageReferences ||= []);
  let packageReference = packageReferences.find(
    (reference) =>
      XCRemoteSwiftPackageReference.is(reference) &&
      reference.props.repositoryURL === MATH_PACKAGE_URL,
  );

  if (!packageReference) {
    packageReference = XCRemoteSwiftPackageReference.create(project, {
      repositoryURL: MATH_PACKAGE_URL,
      requirement: {
        kind: "exactVersion",
        version: MATH_PACKAGE_VERSION,
      },
    });
    packageReferences.push(packageReference);
  } else {
    packageReference.props.requirement = {
      kind: "exactVersion",
      version: MATH_PACKAGE_VERSION,
    };
  }

  const productDependencies = (widgetTarget.props.packageProductDependencies ||=
    []);
  let productDependency = productDependencies.find(
    (dependency) => dependency.props.productName === MATH_PRODUCT_NAME,
  );
  if (!productDependency) {
    productDependency = XCSwiftPackageProductDependency.create(project, {
      package: packageReference,
      productName: MATH_PRODUCT_NAME,
    });
    productDependencies.push(productDependency);
  } else {
    productDependency.props.package = packageReference;
  }

  const frameworksPhase = widgetTarget.getFrameworksBuildPhase();
  const isLinked = frameworksPhase.props.files.some(
    (file) => file.props.productRef?.uuid === productDependency.uuid,
  );
  if (!isLinked) {
    frameworksPhase.createFile({ productRef: productDependency });
  }
}

module.exports = function withWidgetPluginFixes(config) {
  return withXcodeProjectBeta(config, (config) => {
    const project = config.modResults;
    const widgetTarget = project.rootObject.props.targets.find(
      (target) =>
        PBXNativeTarget.is(target) &&
        target.props.productName === WIDGET_TARGET_NAME,
    );
    if (!widgetTarget) {
      throw new Error(`Could not find ${WIDGET_TARGET_NAME} target`);
    }
    widgetTarget.setBuildSetting("SWIFT_VERSION", "6.0");
    widgetTarget.setBuildSetting(
      "SWIFT_ACTIVE_COMPILATION_CONDITIONS",
      "$(inherited) ORBIT_WIDGET_EXTENSION",
    );
    ensureMathRenderingPackage(project, widgetTarget);

    // Compile the actual same handoff source into both processes. CocoaPods
    // already includes it via OrbitAutomerge's Swift source glob.
    const sourcePath =
      "../modules/orbit-automerge/ios/WidgetProjectionStore.swift";
    let fileRef = [...project.values()].find(
      (reference) =>
        PBXFileReference.is(reference) &&
        reference.props.path === sourcePath &&
        reference.props.sourceTree === "SOURCE_ROOT",
    );
    if (!fileRef) {
      fileRef = PBXFileReference.create(project, {
        name: "WidgetProjectionStore.swift",
        path: sourcePath,
        sourceTree: "SOURCE_ROOT",
        lastKnownFileType: "sourcecode.swift",
      });
      project.rootObject.props.mainGroup.props.children.push(fileRef);
    }
    widgetTarget.getSourcesBuildPhase().ensureFile({ fileRef });

    const resourcesPhase = widgetTarget.getResourcesBuildPhase();

    // expo-font creates project references for the app's custom fonts. Reuse
    // those references so the widget can render with the same typefaces.
    const fontReferences = [...project.values()].filter(
      (reference) =>
        PBXFileReference.is(reference) &&
        path.extname(reference.props.path || "").toLowerCase() === ".otf",
    );
    if (fontReferences.length === 0) {
      throw new Error("Could not find Orbit's widget font resources");
    }
    for (const fileRef of fontReferences) {
      resourcesPhase.ensureFile({ fileRef });
    }

    return config;
  });
};
